  function msg(e){var m=String(e&&(e.message||e.error_description||e.error)||'No se pudo completar la operación.');if(/40001|otra sesión/i.test(m))return 'La ficha cambió en otra sesión. Actualiza antes de continuar.';if(/42501|permiso|row-level/i.test(m))return 'Tu rol no permite realizar esta acción.';return m.replace(/^Error:\s*/i,'');}
  function current(s){return s&&state===s&&s.token===sequence&&window.tenantId===s.tenant&&window.pacienteActual&&window.pacienteActual.id===s.patient&&s.root.isConnected;}
