  function date(v,withTime){if(!v)return 'Sin fecha';return new Intl.DateTimeFormat('es-MX',withTime?{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'numeric',month:'short',year:'numeric'}).format(new Date(v));}
  function arr(v){return Array.isArray(v)?v:[];}
