  function defaultHistory(){return {alerts:[],allergies:[],conditions:[],medications:[],surgeries:'',dental_history:'',habits:'',emergency_contact:'',notes:''};}
  function calculatePermissions(s){var owner=window.miRolEquipo==='dueño';var ids=new Set(s.memberRoles.filter(function(x){return x.user_id===s.actor;}).map(function(x){return x.role_id;}));var perms=new Set(s.rolePermissions.filter(function(x){return ids.has(x.role_id);}).map(function(x){return x.permission_key;}));s.canRead=owner||perms.has('clinical.read');s.canWrite=owner||perms.has('clinical.write');s.canApprove=owner||perms.has('clinical.approve');s.canFinanceRead=owner||perms.has('finance.read');s.canFinanceManage=owner||perms.has('finance.manage');s.canInventoryManage=owner||perms.has('inventory.manage');}
