      {key:'treatment',number:'03',label:'Tratamiento',value:planLabel,detail:ctx.dental?(ctx.dental.teeth.total+' piezas documentadas · '+ctx.dental.pending+' por revisar'):'Odontograma y plan en su espacio clínico',tone:ctx.plan&&ctx.plan.saved?'ready':ctx.plan||ctx.selected?'progress':'neutral'},
      {key:'files',number:'04',label:'Estudios y archivos',value:files+' archivo'+(files===1?'':'s')+' · '+studies+' estudio'+(studies===1?'':'s'),detail:'Originales y revisiones permanecen vinculados',tone:files+studies?'ready':'neutral'},
      {key:'appointments',number:'05',label:'Atención y citas',value:upcoming?'Próxima · '+date(upcoming.starts_at):'Sin próxima cita',detail:completed+' atención'+(completed===1?' completada':'es completadas'),tone:upcoming?'ready':'pending'}
