      s.historyHost.innerHTML='<article class="p360-history-workspace p360-history-edit"><header class="p360-history-header"><div><span>ACTUALIZAR HISTORIA CLÍNICA</span><h2>Revisa una sección a la vez</h2><p>Guarda únicamente información confirmada por el paciente.</p></div><button type="button" class="btn btn-secondary" data-history-cancel>Cancelar</button></header><form id="p360-history-form"><section class="p360-history-safety-editor"><div class="p360-history-editor-title"><span class="p360-history-step" aria-hidden="true">01</span><div><strong>Alertas para la atención</strong><small>Se mantienen visibles para el equipo clínico.</small></div><span class="p360-history-required">Prioritario</span></div><div class="p360-form-grid">'+safetyFields+'</div></section><div class="p360-history-form-sections">'+historyEditSection('02','Salud médica','Condiciones, medicamentos y eventos médicos relevantes.',medicalFields,true,'priority')+historyEditSection('03','Antecedentes dentales','Historia odontológica previa del paciente.',dentalFields,false,'clinical')+historyEditSection('04','Hábitos y factores de riesgo','Contexto que puede influir en la atención.',contextFields,false,'clinical')+historyEditSection('05','Información complementaria','Datos de apoyo y observaciones adicionales.',extraFields,false,'administrative')+'</div><div class="p360-actions p360-history-actions"><p>Los cambios crearán una nueva versión del expediente.</p><button type="button" class="btn btn-secondary" data-history-cancel>Cancelar</button><button class="btn btn-primary">Guardar historia</button></div></form></article>';
