  async function saveHistory(s,f){var doc={alerts:csv(f.get('alerts')),allergies:csv(f.get('allergies')),conditions:csv(f.get('conditions')),medications:csv(f.get('medications')),surgeries:String(f.get('surgeries')||'').trim(),dental_history:String(f.get('dental_history')||'').trim(),habits:String(f.get('habits')||'').trim(),emergency_contact:String(f.get('emergency_contact')||'').trim(),notes:String(f.get('notes')||'').trim()};try{s.history=await rpc('smyl_save_patient_history',{p_patient_id:s.patient,p_expected_revision:s.history?s.history.revision:0,p_document:doc});await reloadTimeline(s);historyForm(s,false);renderOverview(s);notify(s,'Historia clínica actualizada.','success');}catch(e){notify(s,msg(e),'error');}}
  function noteTitle(row){return NOTE_TYPES[row.note_type]||'Nota clínica';}
