  function renderNotes(s){s.notesHost.innerHTML='<article class="p360-card"><div class="p360-section-head"><div><span>REGISTRO LONGITUDINAL</span><h2>Notas clínicas</h2><p>Las notas firmadas quedan inmutables. Las correcciones posteriores se agregan como adendas.</p></div>'+(s.canWrite?'<button class="btn btn-primary" data-new-note>Nueva nota</button>':'')+'</div><div class="p360-note-list">'+(s.notes.length?s.notes.map(function(row){var addenda=s.addenda.filter(function(a){return a.note_id===row.id;});return '<article class="p360-note"><div><span class="p360-status" data-status="'+row.status+'">'+(row.status==='signed'?'Firmada':'Borrador')+'</span><h3>'+esc(noteTitle(row))+'</h3><p>'+esc(noteSummary(row))+'</p><small>'+date(row.created_at,true)+' · revisión '+row.revision+'</small>'+(addenda.length?'<div class="p360-addenda"><strong>Adendas</strong>'+addenda.map(function(a){return '<p>'+esc(a.content)+'<small>'+esc(a.reason)+' · '+date(a.created_at,true)+'</small></p>';}).join('')+'</div>':'')+'</div><div>'+(row.status==='draft'&&s.canWrite?'<button data-edit-note="'+row.id+'">Editar</button>':'')+(row.status==='draft'&&s.canApprove?'<button data-sign-note="'+row.id+'">Firmar</button>':'')+(row.status==='signed'&&s.canApprove?'<button data-addendum="'+row.id+'">Agregar adenda</button>':'')+'</div></article>';}).join(''):'<div class="p360-empty">Todavía no hay notas clínicas.</div>')+'</div></article>';var b=s.notesHost.querySelector('[data-new-note]');if(b)b.onclick=function(){openNote(s,null);};s.notesHost.querySelectorAll('[data-edit-note]').forEach(function(x){x.onclick=function(){openNote(s,s.notes.find(function(r){return r.id===x.dataset.editNote;}));};});s.notesHost.querySelectorAll('[data-sign-note]').forEach(function(x){x.onclick=function(){signNote(s,x.dataset.signNote);};});s.notesHost.querySelectorAll('[data-addendum]').forEach(function(x){x.onclick=function(){openAddendum(s,x.dataset.addendum);};});}
  function dialog(s,html){s.dialog.innerHTML=html;s.dialog.showModal();var c=s.dialog.querySelector('[data-close]');if(c)c.onclick=function(){s.dialog.close();};return s.dialog;}
  function openNote(s,row,appointment){var d=row?row.document:{},linkedProfessional=row&&row.professional_id||appointment&&appointment.professional_id||'';var dlg=dialog(s,'<form id="p360-note-form"><h2>'+(row?'Editar nota clínica':appointment?'Evolución de la cita':'Nueva nota clínica')+'</h2><p>'+(appointment?'La nota quedará vinculada a esta cita. ':'')+'Usa campos SOAP y registra solo información clínica confirmada.</p><div class="p360-form-grid"><label>Tipo<select name="type" '+(row?'disabled':'')+'>'+Object.keys(NOTE_TYPES).map(function(k){return '<option value="'+k+'"'+((row&&row.note_type===k)||(!row&&appointment&&k==='progress')?' selected':'')+'>'+NOTE_TYPES[k]+'</option>';}).join('')+'</select></label><label>Profesional<select name="professional"><option value="">Sin asignar</option>'+s.professionals.map(function(p){return '<option value="'+p.id+'"'+(linkedProfessional===p.id?' selected':'')+'>'+esc(p.display_name)+'</option>';}).join('')+'</select></label><label class="wide">Subjetivo · lo referido por el paciente<textarea name="subjective">'+esc(d.subjective||'')+'</textarea></label><label class="wide">Objetivo · hallazgos observados<textarea name="objective">'+esc(d.objective||'')+'</textarea></label><label class="wide">Valoración clínica<textarea name="assessment">'+esc(d.assessment||'')+'</textarea></label><label class="wide">Plan e indicaciones<textarea name="plan">'+esc(d.plan||'')+'</textarea></label></div><div class="p360-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Guardar borrador</button></div></form>');dlg.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget),doc={subjective:String(f.get('subjective')||'').trim(),objective:String(f.get('objective')||'').trim(),assessment:String(f.get('assessment')||'').trim(),plan:String(f.get('plan')||'').trim()};try{if(row)await rpc('smyl_update_clinical_note',{p_id:row.id,p_expected_revision:row.revision,p_document:doc});else await rpc('smyl_create_clinical_note',{p_id:crypto.randomUUID(),p_patient_id:s.patient,p_appointment_id:appointment?appointment.id:null,p_professional_id:f.get('professional')||null,p_note_type:f.get('type'),p_document:doc});s.dialog.close();await refreshClinical(s);notify(s,appointment?'Evolución vinculada a la cita y guardada como borrador.':'Borrador clínico guardado.','success');}catch(err){notify(s,msg(err),'error');}};}
  async function signNote(s,id){var row=s.notes.find(function(x){return x.id===id;});if(!row||!window.confirm('Al firmar, esta nota quedará inmutable. ¿Confirmas que revisaste su contenido?'))return;try{await rpc('smyl_sign_clinical_note',{p_id:id,p_expected_revision:row.revision});await refreshClinical(s);notify(s,'Nota firmada. Las correcciones futuras deberán registrarse como adenda.','success');}catch(e){notify(s,msg(e),'error');}}
  function openAddendum(s,id){var dlg=dialog(s,'<form><h2>Agregar adenda</h2><p>La nota original no cambiará. Esta corrección quedará fechada y vinculada.</p><div class="p360-form-grid"><label class="wide">Motivo<input name="reason" maxlength="500" required></label><label class="wide">Contenido de la adenda<textarea name="content" maxlength="8000" required></textarea></label></div><div class="p360-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Guardar adenda</button></div></form>');dlg.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget);try{await rpc('smyl_add_clinical_note_addendum',{p_note_id:id,p_content:f.get('content'),p_reason:f.get('reason')});s.dialog.close();await refreshClinical(s);notify(s,'Adenda agregada sin modificar la nota firmada.','success');}catch(err){notify(s,msg(err),'error');}};}
  function fiscalComplete(f){return !!(f&&f.rfc&&f.legal_name&&f.fiscal_regime&&f.tax_postal_code&&f.cfdi_use);}
  function renderBilling(s){if(!s.billingHost)return;var f=s.fiscal||{},complete=fiscalComplete(f);s.billingHost.innerHTML='<article class="p360-card p360-billing-card"><div class="p360-section-head"><div><span>ADMINISTRATIVO · FACTURACIÓN</span><h2>Datos fiscales del paciente</h2><p>Estos datos pertenecen al paciente y se usan sólo al preparar su CFDI.</p></div><span class="p360-billing-status" data-complete="'+String(complete)+'">'+(complete?'Información completa':'Faltan datos')+'</span></div><form id="p360-billing-form"><div class="p360-form-grid"><label>RFC<input name="rfc" maxlength="13" value="'+esc(f.rfc||'')+'" required></label><label>Régimen fiscal<input name="regime" pattern="[0-9]{3}" maxlength="3" value="'+esc(f.fiscal_regime||'')+'" placeholder="612" required></label><label class="wide">Nombre o razón social<input name="legal" maxlength="240" value="'+esc(f.legal_name||'')+'" required></label><label>Código postal fiscal<input name="postal" pattern="[0-9]{5}" maxlength="5" value="'+esc(f.tax_postal_code||'')+'" required></label><label>Uso CFDI<input name="use" maxlength="5" value="'+esc(f.cfdi_use||'D01')+'" required></label><label class="wide">Correo de facturación<input name="email" type="email" maxlength="254" value="'+esc(f.email||'')+'"></label></div>'+(s.canFinanceManage?'<div class="p360-actions"><button class="btn btn-primary">Guardar datos fiscales</button></div>':'<p class="p360-readonly">Tu rol puede consultar estos datos, pero no modificarlos.</p>')+'</form><aside class="p360-billing-note"><strong>Separación profesional</strong><span>La historia clínica permanece en sus secciones protegidas. Aquí sólo se conserva información administrativa para facturación.</span></aside></article>';var form=s.billingHost.querySelector('form');if(!s.canFinanceManage)form.querySelectorAll('input').forEach(function(x){x.disabled=true;});else form.onsubmit=async function(e){e.preventDefault();var data=new FormData(form);try{await q(window.sb.from('smyl_patient_fiscal_profiles').upsert({tenant_id:s.tenant,patient_id:s.patient,legal_name:String(data.get('legal')||'').trim().toUpperCase(),rfc:String(data.get('rfc')||'').trim().toUpperCase(),fiscal_regime:data.get('regime'),tax_postal_code:data.get('postal'),cfdi_use:String(data.get('use')||'').trim().toUpperCase(),email:data.get('email'),updated_by:s.actor,updated_at:new Date().toISOString()}));s.fiscal=await q(window.sb.from('smyl_patient_fiscal_profiles').select('*').eq('tenant_id',s.tenant).eq('patient_id',s.patient).maybeSingle());renderBilling(s);notify(s,'Datos fiscales guardados en la ficha del paciente.','success');}catch(err){notify(s,msg(err),'error');}};}
  function renderAppointments(s){s.appointmentsHost.innerHTML='<article class="p360-card"><div class="p360-section-head"><div><span>HISTORIAL DE ATENCIÓN</span><h2>Citas y materiales</h2><p>Registra los insumos desde la atención para mantener inventario, lote y paciente conectados.</p></div><button data-open-agenda>Abrir agenda</button></div><div class="p360-appointment-list">'+(s.appointments.length?s.appointments.map(function(a){var service=s.services.find(function(x){return x.id===a.service_id;}),pro=s.professionals.find(function(x){return x.id===a.professional_id;}),canConsume=s.canInventoryManage&&['in_progress','completed'].indexOf(a.status)>=0;return '<article><time>'+date(a.starts_at,true)+'</time><div><strong>'+esc(service?service.name:'Cita dental')+'</strong><small>'+esc(pro?pro.display_name:'Profesional')+'</small></div><div class="p360-appointment-actions"><span data-status="'+a.status+'">'+esc(a.status)+'</span>'+(canConsume?'<button type="button" data-materials="'+a.id+'">Material utilizado</button>':'')+'</div></article>';}).join(''):'<div class="p360-empty">No hay citas vinculadas a esta ficha.</div>')+'</div></article>';s.appointmentsHost.querySelector('[data-open-agenda]').onclick=function(){window.ir('agenda');};s.appointmentsHost.querySelectorAll('[data-materials]').forEach(function(button){button.onclick=function(){var appointment=s.appointments.find(function(a){return a.id===button.dataset.materials;}),service=appointment&&s.services.find(function(x){return x.id===appointment.service_id;});if(!window.SmylInventory||!window.SmylInventory.openConsumption){notify(s,'El módulo de inventario todavía está cargando.','info');return;}window.SmylInventory.openConsumption({patientId:s.patient,appointmentId:appointment.id,serviceId:appointment.service_id||'',professionalId:appointment.professional_id||'',reason:'Material utilizado · '+(service?service.name:'atención dental')});};});}
  function renderFiles(s){s.filesHost.innerHTML='<article class="p360-card"><div class="p360-section-head"><div><span>ARCHIVO PRIVADO</span><h2>Documentos e imágenes</h2><p>JPG, PNG, WebP o PDF · máximo 20 MB.</p></div>'+(s.canWrite?'<button class="btn btn-primary" data-upload>Agregar archivo</button>':'')+'</div><div class="p360-file-grid">'+(s.files.length?s.files.map(function(f){return '<article><div><span>'+esc(FILE_TYPES[f.category]||'Archivo')+'</span><strong>'+esc(f.display_name)+'</strong><small>'+date(f.created_at,true)+' · '+Math.max(1,Math.round(f.size_bytes/1024))+' KB</small></div><div><button data-open-file="'+f.id+'">Abrir</button>'+(s.canWrite?'<button data-archive-file="'+f.id+'">Archivar</button>':'')+'</div></article>';}).join(''):'<div class="p360-empty">No hay archivos adicionales.</div>')+'</div></article>';var up=s.filesHost.querySelector('[data-upload]');if(up)up.onclick=function(){openFile(s);};s.filesHost.querySelectorAll('[data-open-file]').forEach(function(b){b.onclick=function(){openStoredFile(s,b.dataset.openFile);};});s.filesHost.querySelectorAll('[data-archive-file]').forEach(function(b){b.onclick=function(){archiveFile(s,b.dataset.archiveFile);};});}
  function openFile(s){var dlg=dialog(s,'<form><h2>Agregar archivo clínico</h2><p>Se guardará cifrado en tránsito y dentro del espacio privado de la clínica.</p><div class="p360-form-grid"><label>Tipo<select name="category">'+Object.keys(FILE_TYPES).map(function(k){return '<option value="'+k+'">'+FILE_TYPES[k]+'</option>';}).join('')+'</select></label><label>Fecha de captura<input name="captured" type="date"></label><label class="wide">Archivo<input name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><label class="wide">Notas<textarea name="notes" maxlength="1000"></textarea></label></div><div class="p360-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Subir archivo</button></div></form>');dlg.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget),file=e.currentTarget.elements.file.files[0];if(!file||file.size>20971520){notify(s,'Selecciona un archivo válido de hasta 20 MB.','error');return;}var allowed=['image/jpeg','image/png','image/webp','application/pdf'];if(allowed.indexOf(file.type)<0){notify(s,'Formato no permitido.','error');return;}var id=crypto.randomUUID(),safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)||'archivo',path=s.tenant+'/'+s.patient+'/'+id+'/'+safe;try{var hash=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());var sha=Array.from(new Uint8Array(hash)).map(function(x){return x.toString(16).padStart(2,'0');}).join('');var upload=await window.sb.storage.from('smyl-clinical-files').upload(path,file,{contentType:file.type,upsert:false});if(upload.error)throw upload.error;await window.SmylSecureFiles.verify(window.sb,'smyl-clinical-files',path,file,sha);await rpc('smyl_register_patient_file',{p_id:id,p_patient_id:s.patient,p_appointment_id:null,p_category:f.get('category'),p_display_name:file.name,p_storage_path:path,p_mime_type:file.type,p_size_bytes:file.size,p_sha256:sha,p_notes:f.get('notes')||'',p_captured_at:f.get('captured')?new Date(f.get('captured')+'T12:00:00').toISOString():null});s.dialog.close();await refreshFiles(s);notify(s,'Archivo verificado y guardado en la ficha privada.','success');}catch(err){try{await rpc('smyl_discard_unregistered_file',{p_storage_path:path});}catch(_){}notify(s,msg(err),'error');}};}
  async function openStoredFile(s,id){var f=s.files.find(function(x){return x.id===id;});if(!f)return;try{var result=await window.sb.storage.from('smyl-clinical-files').createSignedUrl(f.storage_path,60);if(result.error)throw result.error;window.open(result.data.signedUrl,'_blank','noopener,noreferrer');}catch(e){notify(s,msg(e),'error');}}
