  function showSection(s,key){var navKey=key==='notes'?'history':key==='appointments'?'overview':key,treatment=key==='treatment',layout=document.getElementById('p-paciente-detalle')&&document.getElementById('p-paciente-detalle').querySelector('.clinic-layout');s.tab=key;s.root.querySelectorAll('[data-p360-tab]').forEach(function(b){b.setAttribute('aria-selected',String(b.dataset.p360Tab===navKey));});s.root.querySelectorAll('[data-p360-panel]').forEach(function(p){p.hidden=treatment||p.dataset.p360Panel!==key;});if(layout)layout.classList.toggle('p360-treatment-hidden',!treatment);}
